CREATE TABLE orders (
  id INTEGER PRIMARY KEY,
  customer TEXT,
  product TEXT,
  category TEXT,
  quantity INTEGER,
  price REAL
);
INSERT INTO orders VALUES
  (1, 'Ana', 'Notebook', 'school', 3, 2.50),
  (2, 'Ben', 'Headphones', 'tech', 1, 25.00),
  (3, 'Ana', 'Pens', 'school', 2, 4.00),
  (4, 'Chen', 'Mouse', 'tech', 1, 15.00),
  (5, 'Dara', 'Backpack', 'school', 1, 30.00),
  (6, 'Ben', 'Notebook', 'school', 5, 2.50),
  (7, 'Chen', 'Cable', 'tech', 2, 6.00),
  (8, 'Ana', 'Headphones', 'tech', 1, 25.00);

SELECT COUNT(*) AS orders, SUM(quantity) AS items FROM orders;
SELECT MIN(price) AS cheapest, MAX(price) AS priciest, ROUND(AVG(price), 2) AS average FROM orders;
SELECT SUM(quantity * price) AS revenue FROM orders;
SELECT COUNT(*) AS school_orders, SUM(quantity * price) AS school_revenue
FROM orders
WHERE category = 'school';

