CREATE TABLE contacts (name TEXT, phone TEXT, email TEXT, age INTEGER);
INSERT INTO contacts VALUES
  ('Ana', '555-0101', 'ana@example.com', 16),
  ('Ben', NULL, 'ben@example.com', 18),
