SELECT name FROM contacts WHERE phone = NULL;
SELECT name FROM contacts WHERE phone IS NULL;
SELECT name, email FROM contacts WHERE email IS NOT NULL;
SELECT COUNT(*) AS everyone, COUNT(phone) AS with_phone, COUNT(age) AS with_age, AVG(age) AS avg_age
FROM contacts;
SELECT name, COALESCE(phone, 'no phone') AS phone FROM contacts;

